import type {PrivateResearchInput} from '../../../src/control/investment-team/private-research.js';

export function researchFixture(){
 const f=finiteFixture(),c=f.company;
 const source=sourceFixture({at:f.clock.now(),policy:{reviewedAt:f.clock.now(),expiresAt:'2026-10-13T10:00:00Z'}});
 const input:PrivateResearchInput={mandate:'Assess fictional ACME historical uncertainty',desiredOutput:'Private comparison of evidence, critique and revised conclusion',constraints:'Authored offline fixture, no Yahoo, inference, orders or publication',participants:[f.first,f.second].map(w=>({workerId:w.worker_id,name:w.display_name,responsibility:w===f.first?'Develop the analysis':'Challenge assumptions independently'})),facilitatorId:f.first.worker_id,synthesizerId:f.first.worker_id,policy:{...f.policy,maxRun:8,maxCycle:8,maxDay:8,maxWorker:5},aiProfile:{...f.input.aiProfile,serviceTier:'default',cliVersion:'0.157.0'},startsAt:'2026-10-12T10:01:00.000Z',expiresAt:'2026-10-12T11:01:00.000Z',retainUntil:'2026-10-12T12:00:00.000Z',source:{policy:source.policy,instruments:[source.market.get<InstrumentIdentity>('ACME','instrument')],calendar:source.calendar,requests:[request()],modelProcessing:{status:'allowed',evidence:['synthetic:authored-fixture'],note:'Only fake model processing is approved in this fixture'}},retention:{localContent:'delete_at_deadline',providerRetention:'No provider; fake runtime only',hostEvidenceHash:hash('fake retention preflight')}};
 source.close();
 const preview=()=>c.privateResearch.preview(input),consent=(collection=true,processing=true)=>{const p=preview();return c.privateResearch.consent({previewId:p.previewId,digest:p.digest,receiptId:randomUUID(),approveCollection:collection,approveModelProcessing:processing});};
 let journal:FiniteJournal|undefined;
 const authorize=(result:ReturnType<typeof consent>)=>{const dir=join(c.dataDir,'research-authority'),custody=join(c.dataDir,'research-custody');mkdirSync(dir,{mode:0o700});mkdirSync(custody,{mode:0o700});journal=FiniteJournal.createFixture(join(dir,'authority.sqlite'),join(custody,'checkpoint.json'),f.clock.now());c.finiteHQ.attach(journal);const account={accountFingerprint:hash('fake-private-account'),routingFingerprint:hash('fake-official-route')};const attestation={authorityId:input.policy.authorityId,runId:result.runId,accountFingerprint:account.accountFingerprint,ownerId:'human',confirmedAt:f.clock.now(),reloadOff:true as const,evidenceHash:hash('fake explicit reload off')};c.finiteHQ.approve(result.scopeId,account,{ownerId:'human',receiptHash:hash('fake-research-approval'),approvedAt:f.clock.now()},attestation);return {journal,account,attestation};};
 const adapter:YahooAdapter={kind:YAHOO_ADAPTER,async read({request:r},exchange){await exchange({method:'GET',url:'https://query1.finance.yahoo.com/v8/finance/chart/ACME',params:{period1:Date.parse('2026-03-06T05:00:00Z')/1000,period2:Date.parse('2026-03-10T04:00:00Z')/1000,interval:'1d',includePrePost:false,events:'div,splits,capitalGains'}});return JSON.stringify(output(r));}};
 const transport:YahooTransport={kind:'authored_yahoo_fixture',async exchange(q){return responseFor(q);}};
 const collect=(result:ReturnType<typeof consent>,override:{adapter:YahooAdapter;transport:YahooTransport}={adapter,transport},signal?:AbortSignal)=>collectPrivateResearch(c,result.scopeId,request(),signal,override);
 return {...f,input,preview,consent,authorize,collect,adapter,transport,close:()=>{journal?.close();f.close();}};
}
export async function runningResearchFixture(maxAgeMs?:number){
 const f=researchFixture(),c=f.company;if(maxAgeMs!==undefined)f.input.source.policy.maxObservationAgeMs=maxAgeMs;const result=f.consent(),authority=f.authorize(result),collection=await f.collect(result);if(!collection.evidenceId)throw Error('Research collection failed: '+JSON.stringify(collection));
 c.investmentTeam.runtime={type:'fake',supportsInterrupt:true,run:async()=>{throw Error('Ordinary runtime forbidden');},finiteHQPolicySupported:()=>true,runFiniteHQInvestment:async()=>{throw Error('Manual fake tests never call a provider');}};
 const control=(action:string)=>c.investmentLoop.control({loopId:result.loop.loopId,action,digest:result.loop.digest,receiptId:randomUUID(),orderId:null});
 control('start');f.clock.set(f.input.startsAt);c.investmentLoop.tick();
 const claim=()=>{const x=c.claimWorkNext();if(!x||x.origin!=='conversation')throw Error('Research claim missing: '+JSON.stringify({loop:c.investmentLoop.get(result.loop.loopId),group:c.discussions.group(result.groupId),authority:c.finiteHQ.inspect(result.scopeId)}));c.conversations.prepareBinding(x.context,c.conversations.binding(x.context)??{worker_id:x.worker.worker_id,runtime_type:'fake',workspace_path:x.worker.workspace_path,runtime_reference:'fake_'+randomUUID(),created_at:f.clock.now()});c.conversations.activateBinding(x.context);c.conversations.context(x.context);c.recordRuntimeConfig(x.context,{model:f.input.aiProfile.model,reasoning_effort:f.input.aiProfile.reasoningEffort,runtime_version:'codex-cli 0.157.0',runtime_adapter:'fake',execution_priority:x.worker.execution_priority});const threadId=c.conversations.binding(x.context)!.runtime_reference,turnId='turn_'+randomUUID();c.aiUsage.observe(x.execution.execution_id,{kind:'start',identity:{threadId,model:f.input.aiProfile.model,provider:'openai',serviceTier:'default',freshThread:true}});c.aiUsage.observe(x.execution.execution_id,{kind:'turn',threadId,turnId});c.investmentActivity.admit(x.context,{threadId,model:f.input.aiProfile.model,...authority.account,eligibility:{authMode:'chatgpt',provider:'openai',planType:'pro',paidCredits:'existing_approved',ordinaryUsageAllowed:false,creditUsageAllowed:true}});authority.journal.transmit(x.execution.execution_id,threadId,{fingerprint:authority.account.accountFingerprint,routingFingerprint:authority.account.routingFingerprint},f.clock.now());return {...x,threadId,turnId};};
 const call=(x:ReturnType<typeof claim>,name:string,args:unknown)=>c.conversations.callTool(x.context,randomUUID(),name,args) as any;
 const read=(x:ReturnType<typeof claim>,evidenceId=collection.evidenceId!)=>{let offset:number|null=0,last;while(offset!==null){last=call(x,'read_financial_evidence',{evidenceId,offset});offset=last.next_offset;}return last;};
 const record=(x:ReturnType<typeof claim>,record_id:string)=>{let offset:number|null=0,last;while(offset!==null){last=call(x,'read_group_record',{record_id,offset});offset=last.next_offset;}return last;};
 const finish=(x:ReturnType<typeof claim>,settled=true)=>{c.aiUsage.observe(x.execution.execution_id,{kind:'response',threadId:x.threadId,turnId:x.turnId,responseId:'response_'+x.execution.execution_id,usage:{...ZERO,inputTokens:100,outputTokens:20,totalTokens:120}});c.finish(x.execution.execution_id,{status:'completed',summary:'Offline fake research response',settled});};
 const contribute=(x:ReturnType<typeof claim>,refs:string[]=[],body='Fixture analysis explicitly preserves historical availability uncertainty')=>{read(x);for(const id of refs)record(x,id);return call(x,'submit_contribution',{body,contribution_ids:refs,evidence_ids:[collection.evidenceId],questions:[],answers:[]});};
 const synthesis=(x:ReturnType<typeof claim>,refs:string[],revised=false)=>{read(x);for(const id of refs)record(x,id);return call(x,'submit_synthesis',{recommendation:revised?'Revised: historical correlation is insufficient for a current decision':'Draft: compare split-adjusted return cautiously',alternatives:'Wait for permitted current evidence',supporting_findings:'Two authored historical rows, not live values',challenges_addressed:revised?'Independent reviewer challenged availability and present-day inference':'Original opposing employee analyses',dissent_and_risks:'Missing provider availability and no contemporaneous price',missing_evidence_and_confidence:'Fixture only; no genuine inference',next_actions_and_approvals:'Owner decision required; no execution authority',contribution_ids:refs,evidence_ids:[collection.evidenceId]});};
 return {...f,result,authority,collection,claim,call,read,record,finish,contribute,synthesis,control};
}
